import {DEFAULT_CONFIG,esc,manila,dates,recordFor,dayStatus,reportCsv,rosterCsv,bridgeOrigin,endpointUrl} from './core.js';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const SITE_ORIGIN='https://josejoaquinvalerio.github.io';
const BACKEND_URL='https://script.google.com/macros/s/AKfycbza6eENNH9Q3rBRcu8wnFs1rOelL2dGz-GoGmabe6NgMFVIyKsQJhrFGwFvRdX-h5klUw/exec';
let demo=true,token='',data,view='overview',selectedDate='2026-10-19',section='all',search='',statusFilter='all',stream=null,capture=null,frame=null,bridgeHost='',bridgeWindow=null,channel='',bridgeReady=null,toastTimer,previewUrl='',cameraFacing='environment',reviewSection='all',reviewSession='all',reviewDate='all',reviewFlags='all';
const reviewSelection=new Set();
const pending=new Map();
const uid=()=>crypto.randomUUID();
const initials=name=>name.split(/[ ,]+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('');
const prettyDate=(s,options={month:'long',day:'numeric',year:'numeric'})=>new Date(s+'T12:00:00+08:00').toLocaleDateString('en-PH',{...options,timeZone:'Asia/Manila'});
const timeLabel=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}${m?':'+String(m).padStart(2,'0'):''} ${h>=12?'PM':'AM'}`};
const windowLabel=k=>`${timeLabel(data.config.sessions[k].start)} – ${timeLabel(data.config.sessions[k].end)}`;
function demoData(){const students=[['DEMO-001','Alex Santos','BSCE 2-A',''],['DEMO-002','Bea Rivera','BSCE 2-A',''],['DEMO-003','Carlo Reyes','BSCE 2-A',''],['DEMO-004','Dani Cruz','BSCE 2-A','COE athlete'],['DEMO-005','Ellis Garcia','BSCE 2-B',''],['DEMO-006','Frankie Ramos','BSCE 2-B',''],['DEMO-007','Gabi Mendoza','BSCE 2-B',''],['DEMO-008','Harper Torres','BSCE 2-B','Student volunteer']].map(([id,name,section,exemption])=>({id,name,section,exemption}));const records=[];for(const [i,s]of students.entries()){if(s.exemption)continue;for(const k of ['AM','PM']){if(i===2&&k==='PM'||i===6)continue;records.push({id:uid(),student_id:s.id,section:s.section,date:'2026-10-19',session:k,rep_id:'demo-rep',status:i===1||i===5?'PENDING':'APPROVED',flags:i===5?'LOW_GPS_ACCURACY':'',captured_at:`2026-10-19T${k==='AM'?'00':'06'}:35:00.000Z`,received_at:`2026-10-19T${k==='AM'?'00':'06'}:35:02.000Z`,lat:'',lng:'',accuracy:'',photo_id:'',reason:''})}}return {actor:{id:'demo-admin',name:'Demo administrator',role:'admin',section:'*'},config:{...structuredClone(DEFAULT_CONFIG),frontendOrigin:SITE_ORIGIN},students,records,representatives:[{id:'demo-rep',name:'Sample section representative',section:'BSCE 2-A',role:'representative',active:'TRUE'}]}}
data=demoData();
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',6500)}
function badge(status,text){return `<span class="badge ${esc(status)}">${status==='APPROVED'||status==='PRESENT'?'✓ ':status==='PENDING'?'◷ ':''}${esc(text||({APPROVED:'Approved',PRESENT:'Present',PENDING:'Pending review',REJECTED:'Rejected',EMPTY:'Not recorded',INCOMPLETE:'Incomplete',ABSENT:'Absent',EXEMPT:'Exempt'}[status]||status))}</span>`}
function visibleStudents(){return data.students.filter(s=>(section==='all'||s.section===section)&&(!search||(s.name+' '+s.id).toLowerCase().includes(search.toLowerCase()))&&(statusFilter==='all'||dayStatus(s,data.records,selectedDate,data.config)===statusFilter))}
function allSections(){return [...new Set(data.students.map(s=>s.section))].sort()}
function shell(content){const isAdmin=data.actor.role==='admin';const queue=data.records.filter(r=>r.status==='PENDING').length;return `<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandmark">↗</div><div>intrams<span style="color:#a5b699">.</span><small>ATTENDANCE DESK</small></div></div><div class="nav-label">EVENT WORKSPACE</div><nav class="nav" aria-label="Main navigation"><button data-view="overview" class="${view==='overview'?'active':''}"><span>▦</span>Overview</button><button data-view="capture" class="${view==='capture'?'active':''}"><span>◎</span>Record attendance</button>${isAdmin?`<button data-view="review" class="${view==='review'?'active':''}"><span>▤</span>Evidence review <b class="count">${queue}</b></button><button data-view="setup" class="${view==='setup'?'active':''}"><span>⚙</span>Event setup</button>`:''}</nav><div class="side-bottom"><div class="secure-note"><strong>⌁ Your Google workspace</strong>${demo?'Explore with sample records. Connect your own Google backend to start.':'Photos stay in your private Drive. Section representatives are restricted to their section; the attendance assistant covers all sections.'}</div><div class="account"><div class="avatar">${esc(initials(data.actor.name))}</div><div>${esc(data.actor.name)}<small>${isAdmin?'Event administrator':data.actor.role==='assistant'?'Attendance assistant · all sections':esc(data.actor.section)+' representative'}</small></div><button data-logout title="${demo?'Connect Google':'Sign out'}" aria-label="${demo?'Connect Google':'Sign out'}">↗</button></div></div></aside><div class="main"><header class="topbar"><span>Workspace <span style="margin:0 10px;color:#b6c0ae">/</span> <strong>${esc(data.config.title)}</strong></span><div class="clock"><span>Asia / Manila</span><span id="clock"></span><button class="btn small" data-refresh aria-label="Refresh attendance">↻</button></div></header><main class="content" id="main">${demo?`<div class="mode-banner"><span>◈ <strong>Demo workspace</strong> · Fictional students. Changes stay in this tab and are not saved to Google.</span><button data-connect>Connect Google ↗</button></div>`:`<div class="mode-banner success"><span><span class="live-dot"></span>Connected to Google · ${esc(data.actor.section==='*'?'All sections':data.actor.section)}</span><button data-logout>Sign out</button></div>`}${content}<footer class="footnote"><span>INTRAMS ${new Date(data.config.startDate).getFullYear()} <span style="margin:0 7px">/</span> Attendance with evidence.</span><span>Both sessions required · Flagged photos require review · No facial recognition</span></footer></main></div></div>`}
function heading(title,description,extra=''){return `<div class="heading"><div><div class="eyebrow">UNIVERSITY MEET / ${esc(prettyDate(data.config.startDate,{month:'short',day:'numeric'}))}–${esc(prettyDate(data.config.endDate,{month:'short',day:'numeric'}))}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`}
function rosterTable(){const students=visibleStudents();return `<div class="workspace"><div class="workspace-head"><div><h2>Section attendance</h2><p>One student. Two sessions. A clear daily record.</p></div><div class="dates" role="group" aria-label="Attendance date">${dates(data.config).map(d=>`<button class="date-btn ${d===selectedDate?'active':''}" aria-pressed="${d===selectedDate}" data-date="${d}">${esc(prettyDate(d,{weekday:'short'}))}<strong>${esc(prettyDate(d,{day:'numeric',month:'short'}))}</strong></button>`).join('')}</div></div><div class="filters"><label class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search students" placeholder="Search student name or ID…" value="${esc(search)}"></label><select id="section" aria-label="Section"><option value="all">All sections</option>${allSections().map(s=>`<option ${section===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="status-filter" aria-label="Day status"><option value="all">All statuses</option>${['PRESENT','PENDING','INCOMPLETE','ABSENT','EXEMPT'].map(s=>`<option value="${s}" ${s===statusFilter?'selected':''}>${esc(s[0]+s.slice(1).toLowerCase())}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>SECTION</th><th>MORNING <span class="wide-only"> / TIME IN</span></th><th>AFTERNOON <span class="wide-only"> / TIME OUT</span></th><th>DAY STATUS</th><th><span class="wide-only">ACTION</span></th></tr></thead><tbody>${students.map(s=>{const am=recordFor(data.records,s.id,selectedDate,'AM'),pm=recordFor(data.records,s.id,selectedDate,'PM');return `<tr><td><div class="student"><div class="avatar">${esc(initials(s.name))}</div><div><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></div></div></td><td>${esc(s.section)}</td>${[am,pm].map(r=>`<td>${s.exemption?badge('EXEMPT'):r?`<button class="badge-link" data-evidence="${esc(r.id)}" aria-label="View ${esc(r.session)} evidence for ${esc(s.name)}">${badge(r.status)}</button>`:badge('EMPTY')}</td>`).join('')}<td>${badge(dayStatus(s,data.records,selectedDate,data.config))}</td><td>${s.exemption?`<span class="pill" title="${esc(s.exemption)}">Exempt</span>`:`<button class="btn small" data-capture="${esc(s.id)}" ${am&&pm&&am.status!=='REJECTED'&&pm.status!=='REJECTED'?'disabled':''}>Record ↗</button>`}${data.actor.role==='admin'?`<button class="btn small" data-manual="${esc(s.id)}">Edit attendance</button>`:''}</td></tr>`}).join('')}</tbody></table>${students.length?'':'<div class="empty">No students match this view.<br>Import your section roster in Event setup to begin.</div>'}</div><div class="table-foot"><span>${students.length} of ${data.students.length} students · ${esc(prettyDate(selectedDate))}</span><div class="legend"><span>AM + PM = full day</span><span>Review before certification</span></div></div></div>`}
function overview(){const list=data.students.filter(s=>section==='all'||s.section===section);const counts=Object.fromEntries(['PRESENT','PENDING','EXEMPT'].map(k=>[k,list.filter(s=>dayStatus(s,data.records,selectedDate,data.config)===k).length]));const missing=list.filter(s=>!s.exemption&&['AM','PM'].some(k=>!recordFor(data.records,s.id,selectedDate,k)||recordFor(data.records,s.id,selectedDate,k).status==='REJECTED')).length;return heading(view==='capture'?'Record attendance':'Attendance overview',view==='capture'?'Select a student below to capture a photo and location.':'A little less paperwork. A clearer picture of who’s here.',`<button class="btn" data-export>↓ Export report</button>`)+`<section class="hero"><div><div class="eyebrow">${esc(data.config.title.toUpperCase())} <span style="color:#6d8c76;margin:0 6px">/</span> COLLEGE OF ENGINEERING</div><h2>Every session counts.</h2><p>Photo evidence, a location check, and a record you can review.</p></div><div class="session-cards"><div class="session-card"><span><i>☀</i> MORNING TIME IN</span><strong>${windowLabel('AM')}</strong></div><div class="session-card"><span><i>◔</i> AFTERNOON TIME OUT</span><strong>${windowLabel('PM')}</strong></div></div></section><div class="stats"><div class="stat"><div class="label">Full day present <span>✓</span></div><strong>${counts.PRESENT}<span style="font-size:13px;letter-spacing:0;color:#a2aa98;font-weight:400"> / ${list.length-counts.EXEMPT}</span></strong><small>Both sessions approved</small></div><div class="stat"><div class="label">Awaiting review <span>◷</span></div><strong>${counts.PENDING}</strong><small>Students with pending evidence</small></div><div class="stat"><div class="label">Missing a session <span>−</span></div><strong>${missing}</strong><small>AM or PM not yet recorded</small></div><div class="stat"><div class="label">Exempt students <span>◇</span></div><strong>${counts.EXEMPT}</strong><small>Approved event duties</small></div></div>${rosterTable()}`}
function reviewRows(){return data.records.filter(r=>r.status==='PENDING'&&(reviewSection==='all'||r.section===reviewSection)&&(reviewSession==='all'||r.session===reviewSession)&&(reviewDate==='all'||r.date===reviewDate)&&(reviewFlags==='all'||(reviewFlags==='clean'?!r.flags:!!r.flags))).sort((a,b)=>a.date.localeCompare(b.date))}
function reviewView(){const pendingRows=reviewRows();const ids=new Set(pendingRows.map(r=>r.id));for(const id of reviewSelection)if(!ids.has(id))reviewSelection.delete(id);return heading('Evidence review','Review individual photos or select up to 50 pending submissions for a batch decision.')+`<section class="panel"><h2>${pendingRows.length} submissions in this view</h2><p>Automatic approval is <strong>${data.config.autoApprove===true?'ON':'OFF'}</strong> for new submissions. Flagged evidence stays pending. Identity and face clarity are not checked automatically.</p><div class="filters"><select id="review-section" aria-label="Review section"><option value="all">All sections</option>${allSections().map(s=>`<option ${reviewSection===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="review-session" aria-label="Review session"><option value="all">Both sessions</option>${['AM','PM'].map(k=>`<option ${reviewSession===k?'selected':''}>${k}</option>`).join('')}</select><select id="review-date" aria-label="Review date"><option value="all">All event dates</option>${dates(data.config).map(d=>`<option ${reviewDate===d?'selected':''}>${d}</option>`).join('')}</select><select id="review-flags" aria-label="Review flags"><option value="all">All evidence</option><option value="clean" ${reviewFlags==='clean'?'selected':''}>No validation flags</option><option value="flagged" ${reviewFlags==='flagged'?'selected':''}>Flagged only</option></select></div><div class="batch-tools"><button class="btn small" id="select-review">Select first 50 in view</button><button class="btn small" id="clear-review">Clear selection</button><strong id="review-count">${reviewSelection.size} selected</strong><button class="btn primary" id="batch-approve" ${reviewSelection.size?'':'disabled'}>Approve selected</button><button class="btn danger" id="batch-reject" ${reviewSelection.size?'':'disabled'}>Reject selected</button></div><p class="help">Changing filters clears your selection. A batch decision requires your review note and confirmation; previously reviewed records are skipped on retry.</p>${pendingRows.map(r=>{const student=data.students.find(s=>s.id===r.student_id);return `<div class="review-card"><input type="checkbox" class="review-check" data-review-select="${esc(r.id)}" aria-label="Select ${esc(student?.name||r.student_id)} ${esc(r.session)} ${esc(r.date)}" ${reviewSelection.has(r.id)?'checked':''}><div><h3>${esc(student?.name||r.student_id)} <span class="pill">${esc(r.session)}</span></h3><p>${esc(r.section)} · ${esc(prettyDate(r.date))}</p>${r.flags?`<div class="flags">⚑ ${esc(r.flags.replaceAll('|',' · '))}</div>`:'<div class="flags">No validation flags · check photo and student identity</div>'}</div><button class="btn small" data-evidence="${esc(r.id)}">Review evidence ↗</button></div>`}).join('')||'<div class="empty">No pending submissions match these filters.</div>'}</section>`}
function updateReviewSelection(){const count=$('#review-count');if(count)count.textContent=reviewSelection.size+' selected';for(const id of ['#batch-approve','#batch-reject'])if($(id))$(id).disabled=!reviewSelection.size}
function bindReview(){for(const [id,key]of [['review-section','section'],['review-session','session'],['review-date','date'],['review-flags','flags']]){const input=$('#'+id);if(input)input.onchange=()=>{if(key==='section')reviewSection=input.value;if(key==='session')reviewSession=input.value;if(key==='date')reviewDate=input.value;if(key==='flags')reviewFlags=input.value;reviewSelection.clear();render()}}app.querySelectorAll('[data-review-select]').forEach(box=>box.onchange=()=>{if(box.checked&&reviewSelection.size>=50){box.checked=false;return toast('Review at most 50 submissions per batch.',true)}box.checked?reviewSelection.add(box.dataset.reviewSelect):reviewSelection.delete(box.dataset.reviewSelect);updateReviewSelection()});if($('#select-review'))$('#select-review').onclick=()=>{reviewSelection.clear();reviewRows().slice(0,50).forEach(r=>reviewSelection.add(r.id));render()};if($('#clear-review'))$('#clear-review').onclick=()=>{reviewSelection.clear();render()};if($('#batch-approve'))$('#batch-approve').onclick=()=>batchReviewDialog('APPROVED');if($('#batch-reject'))$('#batch-reject').onclick=()=>batchReviewDialog('REJECTED')}
function batchReviewDialog(status){const recordIds=[...reviewSelection],rows=data.records.filter(r=>recordIds.includes(r.id)),flagged=rows.filter(r=>r.flags).length;if(!recordIds.length)return;openModal(modalHead(status==='APPROVED'?'Approve selected attendance':'Reject selected attendance')+`<p>You selected <strong>${recordIds.length} session submissions</strong>. ${flagged?`<strong>${flagged} have validation flags.</strong> Check those exceptions before confirming.`:'Confirm that you have checked the evidence and student identities.'}</p><form id="batch-review-form"><label class="stacked">Review note<textarea name="reason" required maxlength="1000" placeholder="Explain the batch decision and any exceptions."></textarea></label><div class="actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn ${status==='APPROVED'?'primary':'danger'}" type="submit">Confirm ${status==='APPROVED'?'approval':'rejection'}</button></div></form>`);$('#batch-review-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,reason=new FormData(form).get('reason').trim();if(!reason)return;form.classList.add('busy');try{const result=await rpc('batchReview',{recordIds,status,reason});reviewSelection.clear();modal.close();await refresh();toast(`${result.updated} submissions updated; ${result.skipped} already reviewed and skipped.`)}catch(err){form.classList.remove('busy');toast(err.message,true)}}}
function accessManagementView(){const active=data.representatives.filter(r=>r.active==='TRUE');return `<section class="panel"><h2>4. Representatives & assistant</h2><p>Assign one active representative per section and one attendance assistant for all sections. Both can view student evidence and record attendance. Only you can approve evidence, change settings or manage access. Revoke an existing code before creating its replacement.</p><form id="rep-form" class="form-grid"><label>Student name<input name="name" required maxlength="100" placeholder="Full name"></label><label>Access type<select name="role" id="access-role"><option value="representative">Section representative</option><option value="assistant">Attendance assistant · all sections</option></select></label><label>Assigned section<select name="section" required><option value="">Choose a section</option>${allSections().map(s=>{const occupied=active.some(r=>r.role==='representative'&&r.section===s);return `<option value="${esc(s)}" ${occupied?'disabled':''}>${esc(s)}${occupied?' — assigned':''}</option>`}).join('')}</select></label><div class="notice full" id="access-help"></div><div class="actions full"><button class="btn primary">Create access code</button></div></form><div id="rep-result"></div>${data.representatives.filter(r=>r.role!=='admin').map(r=>`<div class="review-card"><div class="avatar">${esc(initials(r.name))}</div><div><h3>${esc(r.name)}</h3><p>${r.role==='assistant'?'Attendance assistant · All sections':'Section representative · '+esc(r.section)} · ${r.active==='TRUE'?'Active':'Revoked'}</p></div>${r.active==='TRUE'?`<button class="btn small danger" data-revoke="${esc(r.id)}">Revoke access</button>`:''}</div>`).join('')}</section>`}
function updateAccessForm(){const form=$('#rep-form');if(!form)return;const assistant=form.elements.role.value==='assistant';form.elements.section.disabled=assistant;form.elements.section.required=!assistant;const exists=assistant&&data.representatives.some(r=>r.role==='assistant'&&r.active==='TRUE');form.querySelector('button').disabled=exists;$('#access-help').textContent=exists?'An assistant is already active. Revoke that code before assigning a replacement.':assistant?'This student can record attendance and view evidence across all sections. Settings, access management and evidence approval remain administrator-only.':'Only one representative code can be active for each section. Assigned sections are unavailable until you revoke their current code.'}
function setupView(){const c=data.config;return heading('Event setup','Make this workspace yours. Settings apply to the live Google backend when connected.')+`<section class="panel"><h2>1. Connect your Google workspace</h2><p>The Google backend is already configured. Student records and evidence stay in private Google storage.</p><div class="actions" style="justify-content:flex-start"><button class="btn primary" data-connect>${demo?'Connect Google':'Change connection'}</button><a class="btn" href="setup.html" target="_blank" rel="noopener">Open setup guide ↗</a></div><p class="help">Frontend origin for Google Settings: <code>${esc(location.origin.startsWith('https:')?location.origin:SITE_ORIGIN)}</code></p></section><form id="event-form" class="panel"><h2>2. Dates, sessions & venues</h2><p>Philippine time applies to all attendance. End times include that final minute. Venue coordinates must come from your actual event locations.</p><div class="form-grid"><label>Event title<input name="title" value="${esc(c.title)}" maxlength="100" required></label><label>Maximum GPS uncertainty (metres)<input name="accuracy" type="number" value="${c.maxAccuracy}" min="5" max="500" required></label><label>First event date<input name="startDate" type="date" value="${c.startDate}" required></label><label>Last event date<input name="endDate" type="date" value="${c.endDate}" required></label><label>Morning starts<input name="amStart" type="time" value="${c.sessions.AM.start}" required></label><label>Morning ends<input name="amEnd" type="time" value="${c.sessions.AM.end}" required></label><label>Afternoon starts<input name="pmStart" type="time" value="${c.sessions.PM.start}" required></label><label>Afternoon ends<input name="pmEnd" type="time" value="${c.sessions.PM.end}" required></label><label class="full">Frontend HTTPS origin<input name="origin" type="url" value="${esc(c.frontendOrigin||SITE_ORIGIN)}" required></label><label class="full privacy-check"><input type="checkbox" name="autoApprove" ${c.autoApprove===true?'checked':''}><span>Automatically approve new submissions that pass all validation checks. Flagged evidence stays pending; identity relies on the assigned representative. Existing pending evidence is unchanged.</span></label><label>Photo retention target (days)<input name="retention" type="number" min="1" max="365" value="${c.retentionDays}" required></label><label class="full">Venues (JSON)<textarea name="venues" spellcheck="false" placeholder='[{"id":"Approved venue","lat":YOUR_LATITUDE,"lng":YOUR_LONGITUDE,"radius":150}]'>${esc(JSON.stringify(c.venues,null,2))}</textarea></label></div><div class="notice">${c.venues.length?'Distances are checked against these venues. Borderline or inaccurate readings are flagged.':'No venues configured. Every submission will be flagged for review until you add actual venue coordinates.'} Retention is a policy target; deletion is manual in this version.</div><div class="actions"><button class="btn primary" type="submit">Save event settings</button></div></form><section class="panel"><h2>3. Student roster</h2><p>Import CSV with the headers <code>id,name,section,exemption</code>. Leave exemption blank for regular attendance. An exemption applies to all event dates. Imports add students; existing IDs are protected against accidental overwrite.</p><div class="actions" style="justify-content:flex-start"><a href="roster-template.csv" class="btn" download>↓ CSV template</a><label class="btn">Import roster CSV<input id="roster-file" type="file" accept=".csv,text/csv" hidden></label></div><p class="help">${data.students.length} students across ${allSections().length} sections. Edit existing names or approved exemptions in the private Google Sheet.</p></section>${accessManagementView()}<section class="panel"><h2>5. Photo folders</h2><p>Photos are stored privately by section and event date. Filenames show the session and student name. Administrator supporting images and retakes are labelled separately.</p><button class="btn" id="organize-photos">Organize existing photos</button><p class="help">Moves existing files without replacing photo IDs or changing attendance. Keep this tab open until finished.</p></section>`}
function render(){app.innerHTML=shell(view==='review'?reviewView():view==='setup'?setupView():overview());bind();updateClock()}
function updateClock(){const clock=$('#clock');if(clock)clock.textContent=new Date().toLocaleTimeString('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'})+' PHT'}
setInterval(updateClock,30000);
function bind(){if($('#organize-photos'))$('#organize-photos').onclick=organizePhotosDialog;bindReview();app.querySelectorAll('[data-manual]').forEach(b=>b.onclick=()=>manualAttendanceDialog(b.dataset.manual));app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});app.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;render()});app.querySelectorAll('[data-connect]').forEach(b=>b.onclick=connectDialog);app.querySelectorAll('[data-logout]').forEach(b=>b.onclick=()=>demo?connectDialog():signOut());app.querySelectorAll('[data-capture]').forEach(b=>b.onclick=()=>captureDialog(b.dataset.capture));app.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>evidenceDialog(b.dataset.evidence));app.querySelectorAll('[data-export]').forEach(b=>b.onclick=exportReport);app.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=()=>refresh().catch(e=>toast(e.message,true)));app.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>revokeDialog(b.dataset.revoke));if($('#search'))$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#section'))$('#section').onchange=e=>{section=e.target.value;render()};if($('#status-filter'))$('#status-filter').onchange=e=>{statusFilter=e.target.value;render()};if($('#event-form'))$('#event-form').onsubmit=saveSettings;if($('#roster-file'))$('#roster-file').onchange=importRoster;if($('#rep-form')){$('#rep-form').onsubmit=addRepresentative;$('#access-role').onchange=updateAccessForm;updateAccessForm()}}
async function refresh(){if(!demo){data=await rpc('bootstrap');if(!dates(data.config).includes(selectedDate))selectedDate=data.config.startDate}render()}
function openModal(html){stopCamera();modal.innerHTML=html;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close())}
modal.addEventListener('close',()=>{stopCamera();capture=null;delete modal.dataset.record;modal.innerHTML=''});
function modalHead(title){return `<div class="modal-head"><h2>${title}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>`}
function signOut(){stopCamera();token='';frame?.remove();frame=null;bridgeHost='';for(const p of pending.values())p.reject(new Error('Signed out.'));pending.clear();demo=true;data=demoData();section='all';view='overview';render();connectDialog();toast('Signed out.')}

window.addEventListener('message',event=>{
  if(!frame||!bridgeOrigin(event.origin))return;
  const m=event.data;
  if(m?.channel!==channel)return;
  if(m?.type==='intrams-ready'&&m.version===1&&!bridgeWindow){bridgeHost=event.origin;bridgeWindow=event.source;bridgeReady?.resolve();return}
  if(event.origin!==bridgeHost||event.source!==bridgeWindow||m?.type!=='intrams-response')return;
  const p=pending.get(m.id);if(!p)return;clearTimeout(p.timer);pending.delete(m.id);m.error?p.reject(new Error(m.error)):p.resolve(m.result);
});
function attachBridge(url){frame?.remove();bridgeHost='';bridgeWindow=null;channel=uid();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{frame?.remove();frame=null;reject(new Error('Google bridge did not connect. Check the deployment URL, access setting, and frontendOrigin in the Google Sheet.'))},25000);bridgeReady={resolve:()=>{clearTimeout(timer);resolve()}};frame=document.createElement('iframe');const endpoint=new URL(endpointUrl(url));endpoint.searchParams.set('channel',channel);frame.src=endpoint.href;frame.hidden=true;frame.title='Secure Google attendance connection';document.body.append(frame)})}
function rpc(action,payload={}){if(demo)return demoRpc(action,payload);if(!frame||!bridgeHost||!bridgeWindow)return Promise.reject(new Error('Connect your Google backend first.'));return new Promise((resolve,reject)=>{const id=uid(),timer=setTimeout(()=>{pending.delete(id);reject(new Error('Google did not confirm this request. Keep this page open and retry; saved attendance will not be duplicated.'))},65000);pending.set(id,{resolve,reject,timer});bridgeWindow.postMessage({type:'intrams-request',channel,id,token,action,payload},bridgeHost)})}
function connectDialog(){openModal(modalHead('Sign in to attendance')+`<p>Enter the private access code supplied by your administrator. The Google connection is already configured. Your code stays in memory for this tab only.</p><form id="connect-form"><details><summary class="help">Google connection settings</summary><label class="stacked">Apps Script deployment URL<input name="endpoint" type="url" value="${esc(localStorage.getItem('intrams-endpoint')||BACKEND_URL)}" placeholder="https://script.google.com/macros/s/…/exec" required></label></details><label class="stacked" style="margin-top:15px">Your access code<input name="token" type="password" autocomplete="off" required minlength="32" maxlength="128"></label><div id="connection-error" class="help" aria-live="polite"></div><div class="actions"><a href="setup.html" target="_blank" rel="noopener" class="btn">Setup guide</a><button class="btn primary" type="submit">Connect workspace ↗</button></div></form>`);$('#connect-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const values=new FormData(form);try{const endpoint=endpointUrl(values.get('endpoint').trim());form.querySelector('button').disabled=true;$('#connection-error').textContent='Connecting to your Google workspace…';await attachBridge(endpoint);token=values.get('token').trim();demo=false;const result=await rpc('bootstrap');data=result;localStorage.setItem('intrams-endpoint',endpoint);section='all';selectedDate=dates(data.config).includes(manila().date)?manila().date:data.config.startDate;view='overview';modal.close();render();toast('Google workspace connected.')}catch(err){token='';demo=true;frame?.remove();frame=null;if($('#connection-error')){$('#connection-error').textContent=err.message;$('#connection-error').className='error-box';form.querySelector('button').disabled=false}}}}
async function demoRpc(action,p){switch(action){case'bootstrap':return data;case'challenge':return {nonce:'demo-only',serverAt:new Date().toISOString(),date:selectedDate};case'submit':{const existing=data.records.find(r=>r.id===p.requestId);if(existing)return {id:existing.id,status:existing.status,reused:true};const s=data.students.find(s=>s.id===p.studentId);const prior=recordFor(data.records,s.id,selectedDate,p.session);if(prior&&prior.status!=='REJECTED')throw new Error('Already recorded for this session.');data.records.push({id:p.requestId,student_id:s.id,section:s.section,date:selectedDate,session:p.session,rep_id:data.actor.id,captured_at:p.capturedAt,received_at:new Date().toISOString(),lat:p.geo.lat,lng:p.geo.lng,accuracy:p.geo.accuracy,photo_id:'demo',_photo:p.photo,status:'PENDING',flags:'DEMO_ONLY|VENUES_NOT_CONFIGURED'});return {id:p.requestId,status:'PENDING'}}case'photo':return {data:data.records.find(r=>r.id===p.recordId)?._photo||null};case'review':{const r=data.records.find(r=>r.id===p.recordId);if(!r||r.status!=='PENDING')throw new Error('Already reviewed.');r.status=p.status;r.reason=p.reason;return {ok:true}}case'saveConfig':{if(p.config.startDate>p.config.endDate||p.config.sessions.AM.start>=p.config.sessions.AM.end||p.config.sessions.AM.end>=p.config.sessions.PM.start||p.config.sessions.PM.start>=p.config.sessions.PM.end)throw new Error('Check your dates and session windows.');data.config=p.config;selectedDate=data.config.startDate;return {ok:true}}case'importRoster':if(p.students.some(s=>data.students.some(x=>x.id===s.id)))throw new Error('A student ID already exists.');data.students.push(...p.students);return {count:p.students.length};case'manualAttendance':{data._originalRecords??=structuredClone(data.records);data._overrides??=[];for(const session of p.sessions){data._overrides=data._overrides.filter(o=>!(o.student_id===p.studentId&&o.date===p.date&&o.session===session));if(p.status!=='CLEARED')data._overrides.push({id:'manual-'+uid(),student_id:p.studentId,section:data.students.find(s=>s.id===p.studentId).section,date:p.date,session,status:p.status,reason:p.reason,flags:'ADMIN_MANUAL_OVERRIDE',_photo:p.photo||null,reviewer:data.actor.id,reviewed_at:new Date().toISOString()})}data.records=data._originalRecords.filter(r=>!data._overrides.some(o=>o.student_id===r.student_id&&o.date===r.date&&o.session===r.session)).concat(data._overrides);return {updated:p.sessions.length}}case'batchReview':{const rows=data.records.filter(r=>p.recordIds.includes(r.id)&&r.status==='PENDING');rows.forEach(r=>{r.status=p.status;r.reason=p.reason});return {updated:rows.length,skipped:p.recordIds.length-rows.length}}case'addRepresentative':{const role=p.role||'representative',section=role==='assistant'?'*':p.section;if(data.representatives.some(r=>r.active==='TRUE'&&r.role===role&&(role==='assistant'||r.section===section)))throw new Error('This assignment already has an active code. Revoke it before creating a replacement.');const id=uid();data.representatives.push({id,name:p.name,section,role,active:'TRUE'});return {id,token:'DEMO-ONLY-'+uid(),role,section}}case'revokeRepresentative':data.representatives.find(r=>r.id===p.id).active='FALSE';return {ok:true};default:throw new Error('Unsupported demo action.')}}

function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null}
function captureDialog(id){const student=data.students.find(s=>s.id===id);if(!student||student.exemption)return;const sessions=['AM','PM'].filter(k=>{const r=recordFor(data.records,id,selectedDate,k);return !r||r.status==='REJECTED'});if(!sessions.length)return toast('Both sessions already recorded.');openModal(modalHead('Record attendance')+`<p><strong>${esc(student.name)}</strong> · ${esc(student.section)}<br>${esc(prettyDate(selectedDate))}${demo?' · Demo capture':''}</p><div class="modal-row"><label class="stacked">Session<select id="capture-session">${sessions.map(k=>`<option value="${k}">${k==='AM'?'Morning time in':'Afternoon time out'} · ${windowLabel(k)}</option>`).join('')}</select></label><button class="btn" id="start-camera">Enable camera</button><button class="btn" id="flip-camera" type="button">Flip camera · ${cameraFacing==='user'?'Selfie':'Back'}</button></div><div class="camera-view"><div class="placeholder">◎<br>Use the live camera with the student’s permission.<br>Keep the face and event context visible.</div></div><label class="privacy-check"><input type="checkbox" id="consent"><span>I have informed the student that their photo and location will be recorded for attendance, and the correct student is shown.</span></label><div class="step-status" id="capture-status" role="status">${demo?'Any photo captured in demo stays in memory in this tab.':selectedDate!==manila().date?'Only today’s attendance can be captured. Select today in the dashboard.':'Camera and location permissions are required. Nothing is saved until you submit.'}</div><div class="actions"><button class="btn" id="retake" hidden>Retake</button><button class="btn" id="take-photo" disabled>Capture photo + GPS</button><button class="btn primary" id="submit-photo" disabled>Save attendance ↗</button></div>`);capture={student,session:sessions[0],photo:null,requestId:uid()};$('#capture-session').onchange=e=>{capture.session=e.target.value;capture.photo=null;$('#submit-photo').disabled=true;$('#capture-status').textContent='Session changed. Retake the photo before saving.';$('#retake').click()};$('#start-camera').onclick=startCamera;$('#flip-camera').onclick=async()=>{cameraFacing=cameraFacing==='user'?'environment':'user';capture.photo=null;capture.requestId=uid();$('#submit-photo').disabled=true;$('#retake').hidden=true;$('#flip-camera').textContent='Flip camera · '+(cameraFacing==='user'?'Selfie':'Back');await startCamera()};$('#take-photo').onclick=takePhoto;$('#submit-photo').onclick=submitPhoto;$('#retake').onclick=async()=>{capture.photo=null;capture.requestId=uid();$('#submit-photo').disabled=true;$('#retake').hidden=true;$('#capture-session').disabled=false;$('#start-camera').disabled=false;await startCamera()}}
async function startCamera(){if(!capture)return;const button=$('#start-camera');button.disabled=true;$('#flip-camera').disabled=true;try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera requires HTTPS and a supported browser.');stopCamera();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cameraFacing},width:{ideal:640},height:{ideal:480}},audio:false});if(!capture){stopCamera();return}$('.camera-view').innerHTML='<video id="camera" autoplay playsinline muted></video><span class="camera-label">LIVE CAMERA</span>';const video=$('#camera');video.style.transform=cameraFacing==='user'?'scaleX(-1)':'';video.srcObject=stream;await video.play();$('#take-photo').disabled=false;$('#capture-status').textContent='Camera ready. Select the session and position the student before capture.'}catch(e){if($('#capture-status'))$('#capture-status').textContent=e.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser’s site settings.':e.message}finally{if($('#start-camera'))$('#start-camera').disabled=false;if($('#flip-camera'))$('#flip-camera').disabled=false}}
function position(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('Location is unavailable in this browser.'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,timestamp:p.timestamp}),e=>reject(new Error(e.code===1?'Location permission denied. Allow location access in your browser settings.':'Could not get a current location. Move to an open area and retry.')),{enableHighAccuracy:true,maximumAge:0,timeout:20000})})}
async function takePhoto(){if(!capture||!$('#camera'))return;if(!$('#consent').checked)return toast('Confirm that the student was informed and correctly identified.',true);$('#take-photo').disabled=true;$('#flip-camera').disabled=true;$('#capture-session').disabled=true;$('#start-camera').disabled=true;try{if(!demo&&selectedDate!==manila().date)throw new Error('Only today’s attendance can be captured.');$('#capture-status').textContent='Opening capture session and requesting a fresh GPS location…';const started=performance.now(),challenge=await rpc('challenge',{studentId:capture.student.id,session:capture.session});const elapsedStart=performance.now();const geo=await position();if(!capture)return;const video=$('#camera');if(!video?.videoWidth)throw new Error('Camera not ready. Enable the camera and retry.');const canvas=document.createElement('canvas');const scale=Math.min(1,640/Math.max(video.videoWidth,video.videoHeight));canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);const ctx=canvas.getContext('2d');ctx.drawImage(video,0,0,canvas.width,canvas.height);const capturedAt=new Date(Date.parse(challenge.serverAt)+(performance.now()-elapsedStart)+(elapsedStart-started)/2).toISOString();const font=Math.max(13,Math.round(canvas.width/65));ctx.fillStyle='rgba(8,28,21,.8)';ctx.fillRect(0,canvas.height-font*6,canvas.width,font*6);ctx.fillStyle='#fff';ctx.font=`${font}px sans-serif`;const stamp=[`${capture.student.name} | ${capture.student.id} | ${capture.session}`,new Date(capturedAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})+' PHT',`${geo.lat.toFixed(6)}, ${geo.lng.toFixed(6)} | accuracy ±${Math.round(geo.accuracy)} m`,'Intrams app stamp • device GPS, subject to review'];stamp.forEach((s,i)=>ctx.fillText(s,font,canvas.height-font*4.5+i*font*1.25,canvas.width-font*2));let photo=canvas.toDataURL('image/jpeg',.5);for(const quality of [.4,.3]){if(photo.length<=205000)break;photo=canvas.toDataURL('image/jpeg',quality)}if(photo.length>2200000)throw new Error('Photo is too large. Try again with a lower camera resolution.');capture={...capture,photo,geo,capturedAt,nonce:challenge.nonce,source:'camera'};$('.camera-view').innerHTML=`<img src="${photo}" alt="Captured attendance evidence"><span class="camera-label">READY FOR REVIEW</span>`;stopCamera();$('#submit-photo').disabled=false;$('#flip-camera').disabled=false;$('#retake').hidden=false;$('#capture-status').textContent=`Photo ready. GPS uncertainty ±${Math.round(geo.accuracy)} m · ${Math.round((photo.length-photo.indexOf(',')-1)*.75/1024)} KB. Save within two minutes. ${geo.accuracy>data.config.maxAccuracy?'Low accuracy will be flagged for review.':''}`}catch(e){if($('#capture-status')){$('#capture-status').textContent=e.message;$('#take-photo').disabled=false;$('#flip-camera').disabled=false;$('#capture-session').disabled=false;$('#start-camera').disabled=false}}}
async function submitPhoto(){if(!capture?.photo)return;const current=capture;$('#submit-photo').disabled=true;$('#flip-camera').disabled=true;$('#retake').disabled=true;$('#capture-status').textContent=demo?'Saving demo evidence in this tab…':'Uploading to your private Google Drive and recording attendance…';try{const result=await rpc('submit',{requestId:current.requestId,studentId:current.student.id,session:current.session,nonce:current.nonce,photo:current.photo,geo:current.geo,capturedAt:current.capturedAt,source:current.source});modal.close();await refresh();toast(`${current.session} saved for ${current.student.name}. ${result.status==='APPROVED'?'Automatically approved.':'Pending review.'}${result.reused?' Original receipt recovered.':''}`)}catch(e){if($('#capture-status')){$('#capture-status').textContent=e.message;$('#submit-photo').disabled=false;$('#flip-camera').disabled=false;$('#retake').disabled=false}}}

async function evidenceDialog(id){const r=data.records.find(r=>r.id===id),student=data.students.find(s=>s.id===r?.student_id);if(!r)return;const isManual=r.flags==='ADMIN_MANUAL_OVERRIDE';const canReview=data.actor.role==='admin'&&r.status==='PENDING';openModal(modalHead('Attendance evidence')+`<p><strong>${esc(student?.name||r.student_id)}</strong> · ${esc(r.section)}<br>${esc(prettyDate(r.date))} · ${esc(r.session)} · ${badge(r.status)}</p><div id="evidence-image" class="empty">Loading private photo…</div>${isManual?'<div class="notice">Administrator correction. Any attached gallery photo is supporting evidence; its capture time and GPS have not been verified by this app.</div>':''}<div class="details">Capture time: ${esc(r.captured_at?new Date(r.captured_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'}):'—')} PHT<br>Server receipt: ${esc(r.received_at?new Date(r.received_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'}):'—')} PHT<br>Location: ${r.lat!==''?esc(r.lat+', '+r.lng):'Demo — no location evidence'} · Accuracy: ${esc(r.accuracy||'—')} m<br>Venue: ${esc(r.venue_id||'Unconfirmed')} · Distance: ${esc(r.distance||'—')} m</div>${r.flags?`<div class="notice">Flags: ${esc(r.flags.replaceAll('|',' · '))}</div>`:''}${r.reason?`<p>Review note: ${esc(r.reason)}</p>`:''}${canReview?`<form id="review-form"><label class="stacked">Review note<textarea name="reason" maxlength="1000" required placeholder="Confirm face, event context and location; explain any approved exception."></textarea></label><div class="actions"><button type="submit" name="decision" value="REJECTED" class="btn danger">Reject evidence</button><button type="submit" name="decision" value="APPROVED" class="btn primary">Approve attendance</button></div></form>`:'<div class="actions"><button class="btn" data-close>Close</button></div>'}`);modal.dataset.record=id;if(canReview)$('#review-form').onsubmit=async e=>{e.preventDefault();const status=e.submitter.value,form=e.currentTarget;const reason=new FormData(form).get('reason').trim();if(!reason)return;form.classList.add('busy');try{await rpc('review',{recordId:r.id,status,reason});modal.close();await refresh();toast(status==='APPROVED'?'Session approved.':'Evidence rejected. Representative may retake this session.')}catch(err){form.classList.remove('busy');toast(err.message,true)}};try{const result=await rpc('photo',{recordId:id});if(!modal.open||modal.dataset.record!==id||!$('#evidence-image'))return;$('#evidence-image').className='';$('#evidence-image').innerHTML=result.data?`<img class="review-photo" src="${esc(result.data)}" alt="Photo evidence for ${esc(student?.name||r.student_id)}">`:`<div class="empty">${isManual?'Administrator correction — no supporting photo attached.':'Sample record — no real photo attached.<br>Connect Google to review actual evidence.'}</div>`}catch(e){if(modal.open&&modal.dataset.record===id&&$('#evidence-image'))$('#evidence-image').textContent=e.message}}
function exportReport(){download(reportCsv(visibleStudents(),data.records,selectedDate,data.config),`intrams-${selectedDate}${demo?'-DEMO':''}.csv`,'text/csv;charset=utf-8');toast(demo?'Demo report exported. Sample records only.':'Report exported for the current filters. Pending evidence is not certified present.')}
function download(content,name,type){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=previewUrl;a.download=name;a.click()}
async function saveSettings(e){e.preventDefault();const form=e.currentTarget,f=new FormData(form);try{const config={...data.config,title:f.get('title').trim(),startDate:f.get('startDate'),endDate:f.get('endDate'),maxAccuracy:Number(f.get('accuracy')),sessions:{AM:{start:f.get('amStart'),end:f.get('amEnd')},PM:{start:f.get('pmStart'),end:f.get('pmEnd')}},frontendOrigin:f.get('origin').replace(/\/$/,''),retentionDays:Number(f.get('retention')),autoApprove:f.get('autoApprove')==='on',venues:JSON.parse(f.get('venues')||'[]')};if(!demo&&config.frontendOrigin!==location.origin)throw new Error('Frontend origin must match this website. Changing it would disconnect your workspace.');form.classList.add('busy');await rpc('saveConfig',{config});await refresh();toast(demo?'Demo event settings updated for this tab.':'Google event settings saved.')}catch(err){form.classList.remove('busy');toast(err.message,true)}}
async function importRoster(e){const file=e.target.files[0];if(!file)return;if(file.size>1500000)return toast('CSV is too large. Import at most 5,000 students at a time.',true);try{const students=rosterCsv(await file.text());if(!students.length||students.length>5000)throw new Error('Import 1–5,000 students.');openModal(modalHead('Import roster')+`<p>Import <strong>${students.length} students</strong> across ${new Set(students.map(s=>s.section)).size} sections? Existing students will be preserved; duplicate IDs stop the whole import.</p><p>First student: ${esc(students[0].name)} · ${esc(students[0].section)}</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="confirm-import">Import students</button></div>`);$('#confirm-import').onclick=async e=>{e.currentTarget.disabled=true;try{const result=await rpc('importRoster',{students});modal.close();await refresh();toast(`${result.count} students imported${demo?' into demo only':''}.`)}catch(err){toast(err.message,true);if($('#confirm-import'))$('#confirm-import').disabled=false}}}catch(err){toast(err.message,true)}finally{if($('#roster-file'))$('#roster-file').value=''}}
async function addRepresentative(e){e.preventDefault();const form=e.currentTarget,f=new FormData(form);form.classList.add('busy');try{const result=await rpc('addRepresentative',{name:f.get('name').trim(),section:f.get('section'),role:f.get('role')});await refresh();$('#rep-result').innerHTML=`<div class="notice"><strong>${demo?'Demo code — does not grant real access.':'Save this code now. It is shown only once.'}</strong><p>Give this student the website URL and this code privately. One code is active per assignment; the code itself can still be copied, so share it only with the assigned student. Revoke and recreate if lost.</p><div class="code-output">${esc(result.token)}</div></div>`;$('#rep-result').scrollIntoView({block:'center',behavior:'smooth'})}catch(err){toast(err.message,true);form.classList.remove('busy')}}
function revokeDialog(id){const rep=data.representatives.find(r=>r.id===id);openModal(modalHead('Revoke attendance access')+`<p>Revoke access for <strong>${esc(rep.name)}</strong> (${rep.role==='assistant'?'All sections':esc(rep.section)})? Their code will stop working. Submitted attendance stays in the records.</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn danger" id="confirm-revoke">Revoke access</button></div>`);$('#confirm-revoke').onclick=async e=>{e.currentTarget.disabled=true;try{await rpc('revokeRepresentative',{id});modal.close();await refresh();toast('Attendance access revoked.')}catch(err){toast(err.message,true);if($('#confirm-revoke'))$('#confirm-revoke').disabled=false}}}
render();
if(BACKEND_URL)connectDialog();

function manualAttendanceDialog(id){
  if(data.actor.role!=='admin')return;
  const student=data.students.find(s=>s.id===id);if(!student)return;
  let supportPhoto=null;const requestId=uid();
  openModal(modalHead('Edit attendance')+`<p><strong>${esc(student.name)}</strong> · ${esc(student.section)}</p><div class="notice">Your correction overrides the selected session’s attendance. Original submissions stay in the history. A reason is required. Choose both sessions only when you intend to mark the full day.</div><form id="manual-attendance-form"><div class="form-grid"><label>Date<select name="date">${dates(data.config).filter(d=>d<=manila().date).map(d=>`<option ${d===selectedDate?'selected':''}>${d}</option>`).join('')}</select></label><label>Session<select name="session"><option value="AM">Morning only</option><option value="PM">Afternoon only</option><option value="BOTH">Both sessions · full day</option></select></label><label class="full">Decision<select name="status"><option value="APPROVED">Mark present</option><option value="ABSENT">Mark absent</option><option value="CLEARED">Remove manual correction · restore original records</option></select></label><label class="full">Reason for correction<textarea name="reason" required maxlength="1000" placeholder="Explain your decision, for example: checked the assistant’s gallery photo and confirmed this student attended the morning session."></textarea></label><label class="full">Optional supporting photo from gallery<input id="manual-photo" type="file" accept="image/*"></label></div><p class="help">Gallery photos are supporting evidence only. The app does not certify their original capture time or location. You can also make a correction without a photo.</p><div id="manual-photo-status" class="help" role="status"></div><div class="actions"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary" type="submit">Save correction</button></div></form>`);
  const form=$('#manual-attendance-form');
  $('#manual-photo').onchange=async e=>{const file=e.target.files[0];supportPhoto=null;if(!file){$('#manual-photo-status').textContent='';return}form.querySelector('[type="submit"]').disabled=true;$('#manual-photo-status').textContent='Preparing a smaller supporting photo…';let bitmap;try{if(file.size>25000000)throw new Error('Choose an image smaller than 25 MB.');bitmap=await createImageBitmap(file);const scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);supportPhoto=canvas.toDataURL('image/jpeg',.5);if($('#manual-photo-status'))$('#manual-photo-status').textContent='Supporting photo ready · '+Math.round(supportPhoto.length*.75/1024)+' KB. Original time and location are unverified.'}catch(err){e.target.value='';if($('#manual-photo-status'))$('#manual-photo-status').textContent=err.message||'Cannot read this image. Try a JPEG photo.'}finally{bitmap?.close();if(form.isConnected)form.querySelector('[type="submit"]').disabled=false}};
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),reason=f.get('reason').trim();if(!reason)return;const sessions=f.get('session')==='BOTH'?['AM','PM']:[f.get('session')];form.classList.add('busy');try{await rpc('manualAttendance',{requestId,studentId:id,date:f.get('date'),sessions,status:f.get('status'),reason,photo:supportPhoto});selectedDate=f.get('date');modal.close();await refresh();toast('Administrator correction saved. Original submissions are preserved.')}catch(err){form.classList.remove('busy');toast(err.message,true)}};
}

function organizePhotosDialog(){if(data.actor.role!=='admin')return;openModal(modalHead('Organize existing photos')+'<p>Arrange photos in your private evidence folder by section and date, with readable student names. Attendance and photo contents are preserved.</p><div id="organize-progress" class="notice" role="status">Ready. This may take several minutes for a large archive.</div><div class="actions"><button class="btn" data-close>Close</button><button class="btn primary" id="start-organize">Start organizing</button></div>');$('#start-organize').onclick=async()=>{const start=$('#start-organize'),progress=$('#organize-progress');start.disabled=true;let total=0;try{if(demo){progress.textContent='Demo only. No real Drive files were moved.';return}while(modal.open){progress.textContent=total+' photos organized. Working on the next batch…';const result=await rpc('organizeEvidence');total+=result.moved;progress.textContent=total+' photos organized in this run; '+result.remaining+' left in the main folder.';if(result.errors?.length||result.unmatched?.length){progress.textContent+=' Some files need administrator attention. No files were deleted. '+(result.errors||[]).map(e=>e.error).join(' ');break}if(!result.remaining){progress.textContent+=' Complete.';break}if(!result.moved){progress.textContent+=' No further progress; please retry.';break}}}catch(e){progress.textContent='Paused: '+e.message+' Photos already moved are preserved; you can safely retry.'}finally{if(start.isConnected)start.disabled=false}}}
